package components

import (
	"strings"

	"charm.land/bubbles/v2/textinput"
	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/ui/theme"
)

// FilterToken is a named toggle filter that can be active or inactive.
// Active tokens are shown as highlighted labels in the filter bar.
type FilterToken struct {
	Label  string
	Active bool
}

// FilterBar is a single-line bar rendered at the bottom of a table viewport.
// It is hidden when no filter is active and appears automatically when:
//   - A toggle filter token is activated
//   - The user presses "/" to enter search mode
//
// Usage:
//
//	fb := components.NewFilterBar()
//	// or with toggle tokens:
//	fb := components.NewFilterBarWithTokens([]components.FilterToken{
//	    {Label: "tcp"}, {Label: "udp"},
//	})
//
// In resize: tableHeight := height - fb.ExtraHeight()
// In view:   append fb.View() as the last line after the table
// In update: forward keys to fb.Update(msg) when fb.InEditMode()
type FilterBar struct {
	searching   bool
	searchInput textinput.Model
	searchQuery string
	tokens      []FilterToken
	width       int
}

// NewFilterBar creates a FilterBar with no toggle tokens (text search only).
func NewFilterBar() FilterBar {
	return newFilterBar(nil)
}

// NewFilterBarWithTokens creates a FilterBar with the given toggle tokens.
func NewFilterBarWithTokens(tokens []FilterToken) FilterBar {
	return newFilterBar(tokens)
}

func newFilterBar(tokens []FilterToken) FilterBar {
	si := textinput.New()
	theme.StyleTextInput(&si)
	si.CharLimit = 100

	fb := FilterBar{
		searchInput: si,
	}
	if len(tokens) > 0 {
		fb.tokens = make([]FilterToken, len(tokens))
		copy(fb.tokens, tokens)
	}
	return fb
}

// IsVisible returns true when the bar should be rendered (searching, query set, or any token active).
func (fb *FilterBar) IsVisible() bool {
	if fb.searching || fb.searchQuery != "" {
		return true
	}
	for _, t := range fb.tokens {
		if t.Active {
			return true
		}
	}
	return false
}

// ExtraHeight returns 2 when the bar is visible (1 separator + 1 bar), 0 otherwise.
// Subtract this from the table height so the bar doesn't overlap table rows.
func (fb *FilterBar) ExtraHeight() int {
	if fb.IsVisible() {
		return 2
	}
	return 0
}

// Resize updates the display width used when rendering.
func (fb *FilterBar) Resize(width int) {
	fb.width = width
}

// InEditMode returns true when the search input is focused.
// Views must propagate this via their own InEditMode() to block command mode.
func (fb *FilterBar) InEditMode() bool {
	return fb.searching
}

// SearchQuery returns the current confirmed search string.
func (fb *FilterBar) SearchQuery() string {
	return fb.searchQuery
}

// ActivateSearch focuses the search input and returns the blink command.
func (fb *FilterBar) ActivateSearch() tea.Cmd {
	fb.searching = true
	fb.searchInput.Focus()
	return textinput.Blink
}

// EndSearch leaves the search input without touching the query: the text typed
// so far stays applied, as if enter had been pressed. A view calls it when
// something else must take the keyboard.
func (fb *FilterBar) EndSearch() {
	fb.searching = false
	fb.searchQuery = fb.searchInput.Value()
	fb.searchInput.Blur()
}

// ClearSearch clears the search query and blurs the input.
func (fb *FilterBar) ClearSearch() {
	fb.searching = false
	fb.searchQuery = ""
	fb.searchInput.SetValue("")
	fb.searchInput.Blur()
}

// IsTokenActive returns true if the token with the given label is active.
func (fb *FilterBar) IsTokenActive(label string) bool {
	for _, t := range fb.tokens {
		if t.Label == label {
			return t.Active
		}
	}
	return false
}

// SetTokenActive sets the active state of the token with the given label.
func (fb *FilterBar) SetTokenActive(label string, active bool) {
	for i, t := range fb.tokens {
		if t.Label == label {
			fb.tokens[i].Active = active
			return
		}
	}
}

// SetTokens replaces the token list. Active state is preserved for tokens
// whose label matches an existing active token.
func (fb *FilterBar) SetTokens(tokens []FilterToken) {
	activeLabels := make(map[string]bool)
	for _, t := range fb.tokens {
		if t.Active {
			activeLabels[t.Label] = true
		}
	}
	fb.tokens = make([]FilterToken, len(tokens))
	copy(fb.tokens, tokens)
	for i, t := range fb.tokens {
		if activeLabels[t.Label] {
			fb.tokens[i].Active = true
		}
	}
}

// Update handles key messages when the bar is in search mode.
// It returns the updated FilterBar and a Bubble Tea command.
// Call this from the view's Update() when fb.InEditMode() is true.
func (fb *FilterBar) Update(msg tea.Msg) (FilterBar, tea.Cmd) {
	if !fb.searching {
		return *fb, nil
	}
	if paste, ok := msg.(tea.PasteMsg); ok {
		// A paste is text for the search input, never an action key. The
		// input turns newlines into spaces itself.
		var cmd tea.Cmd
		fb.searchInput, cmd = fb.searchInput.Update(paste)
		fb.searchQuery = fb.searchInput.Value()
		return *fb, cmd
	}
	keyMsg, ok := msg.(tea.KeyPressMsg)
	if !ok {
		return *fb, nil
	}
	switch keyMsg.String() {
	case "esc":
		fb.searching = false
		fb.searchQuery = ""
		fb.searchInput.SetValue("")
		fb.searchInput.Blur()
		return *fb, nil
	case "enter":
		fb.searching = false
		fb.searchQuery = fb.searchInput.Value()
		fb.searchInput.Blur()
		return *fb, nil
	}
	var cmd tea.Cmd
	fb.searchInput, cmd = fb.searchInput.Update(msg)
	fb.searchQuery = fb.searchInput.Value()
	return *fb, cmd
}

// View renders the filter bar as two lines forming a closed rectangle.
// The viewport's bottom border (└──────┘) serves as the top of the rectangle.
//
// Line 1 (content): │  / cursor...   [tcp] · [LISTEN]  │
// Line 2 (bottom):  └──────────────────────────────────┘
func (fb *FilterBar) View() string {
	var right string
	if len(fb.tokens) > 0 {
		var activeTokens []string
		for _, t := range fb.tokens {
			if t.Active {
				activeTokens = append(activeTokens, theme.KeyStyle.Render(t.Label))
			}
		}
		if len(activeTokens) > 0 {
			right = "  " + strings.Join(activeTokens, theme.DimStyle.Render("  ·  "))
		}
	}

	var left string
	if fb.searching {
		left = theme.KeyStyle.Render("/") + theme.Bg(" ") + fb.searchInput.View()
	} else {
		if fb.searchQuery != "" {
			left = theme.DimStyle.Render("/ ") + theme.KeyStyle.Render(fb.searchQuery)
		} else {
			left = theme.DimStyle.Render("/ search...")
		}
	}

	return BarFrame(fb.width, theme.Bg(" ")+left+theme.Bg(right))
}
package components

import (
	"strings"

	"charm.land/lipgloss/v2"
	"github.com/charmbracelet/x/ansi"

	"github.com/anthnel/devdesk/internal/ui/theme"
)

// BarFrame draws one line of content inside the rectangle that closes the
// viewport, and the rectangle's bottom edge under it.
//
// The viewport's own bottom border serves as the top of the rectangle, so the
// two lines here are the sides and the floor. The router detects the bar from
// the shape of the footer's first line (OpensWithBarFrame; no view declares
// it) and turns the viewport's last line from └…┘ into ├…┤. A footer therefore
// starts with a │…│ line only through BarFrame:
//
//	├────────────────────────────────────┤  (viewport's last line, joined)
//	│  / cursor...                    Aa │
//	└────────────────────────────────────┘
//
// It is shared rather than copied because two things now occupy that one slot —
// the filter bar and the viewer's go-to-line prompt — and a second
// implementation of the frame would be free to disagree with the first about
// where the corners are. `inner` is already styled; it is padded to the width
// between the sides, so a caller measures nothing.
func BarFrame(width int, inner string) string {
	if width == 0 {
		width = 80
	}

	borderStyle := lipgloss.NewStyle().Foreground(theme.ColorViewportBorder).Background(theme.ColorBackground)

	// width-2 to leave room for │ on each side.
	padded := theme.PadWithBg(inner, width-2)
	content := borderStyle.Render("│") + padded + borderStyle.Render("│")
	bottom := borderStyle.Render("└" + strings.Repeat("─", width-2) + "┘")
	return content + "\n" + bottom
}

// OpensWithBarFrame reports whether a rendered footer starts with a BarFrame:
// a first line framed by │ on both sides and a second line closed by └…┘. The
// router reads it to turn the viewport's bottom corners into ├ ┤, so the join
// follows what the footer really draws rather than what a view claims.
func OpensWithBarFrame(footer string) bool {
	lines := strings.SplitN(ansi.Strip(footer), "\n", 3)
	if len(lines) < 2 {
		return false
	}
	return strings.HasPrefix(lines[0], "│") && strings.HasSuffix(lines[0], "│") &&
		strings.HasPrefix(lines[1], "└") && strings.HasSuffix(lines[1], "┘")
}
package components

import "charm.land/bubbles/v2/textinput"

// ReseatInput rebuilds the scroll window of a textinput for its current width,
// keeping its value, cursor position and Err.
//
// bubbles scrolls a textinput through two internal offsets (offset and
// offsetRight) that only SetCursor, SetValue and Update refresh. After a
// SetWidth that shrinks the field, a cursor still inside the old window leaves
// that too wide window in place: the view overflows its box and the cursor cell
// can land beyond it (bubbles v2.2.1 and v2.2.2). Call it after every SetWidth
// that can shrink a field, from Update only (Rule 110), never from View.
//
// SetValue clears Err when the field has no validator, so Err is restored. With
// a validator, SetValue runs it two more times (with "" and with the value),
// which must therefore be cheap and free of side effects. Suggestions, CharLimit
// and focus are not touched.
//
// It rebuilds the window from the end of the line, so call it only when the
// width changed: on a field that fits, with the cursor in the middle of a
// window, it scrolls the line for no reason.
//
// Remove it the day bubbles refreshes its window in SetWidth:
// TestShrinkWithoutReseatLeavesTheCursorOutside goes red then.
func ReseatInput(in *textinput.Model) {
	value, pos, err := in.Value(), in.Position(), in.Err
	in.SetValue("")
	in.SetValue(value)
	in.SetCursor(pos)
	in.Err = err
}
