9		"github.com/charmbracelet/x/ansi"
10	)
11	
12	// Cell decoding (DEVDESK-281). A rendered frame is a string of text and SGR
13	// sequences; two frames can differ byte for byte (a redundant reset, a colour
14	// written as 24-bit or as the same palette entry) and still paint the same
15	// screen. A test that guards a change to how a frame is built therefore
16	// compares cells: what the terminal would show at each position.
17	//
18	// The decoder walks the frame with x/ansi's sequence decoder (the same
19	// grapheme clustering and widths Lip Gloss and the viewport measure with) and
20	// follows the SGR state. It tracks the foreground, the background and reverse
21	// video, nothing else: bold, underline (and the underline colour, SGR 58 and 59,
22	// whose parameters are consumed and dropped) and the like do not change which
23	// colour a cell has, which is what the Rule 115 check and the golden compare. Every
24	// sequence that is not an SGR (cursor moves, erases, OSC titles, hyperlinks,
25	// progress) is skipped and paints nothing.
26	
27	// DefaultColor is the colour of a cell no sequence has coloured: the
28	// terminal's own foreground or background.
29	const DefaultColor = ""
30	
31	// Colour names a Cell carries. A colour is DefaultColor, "#rrggbb" for a 24-bit
32	// one, "ansi:N" for palette entries 0 to 15 (SGR 30-37, 90-97, 40-47, 100-107
33	// and 38;5;N or 48;5;N with N below 16, which a terminal draws the same) and
34	// "idx:N" for entries 16 to 255. Under reverse video the two colours swap; a
35	// default one that lands on the other side is not the terminal's background
36	// (nor foreground) any more, so it is named for what it now is:
37	const (
38		// ReversedDefaultFG is the background of a reversed cell whose foreground was
39		// the terminal's default: the terminal's default foreground, as a fill.
40		ReversedDefaultFG = "default-fg"
41		// ReversedDefaultBG is the foreground of a reversed cell whose background was
42		// the terminal's default.
43		ReversedDefaultBG = "default-bg"
44	)
45	
46	// Cell is one terminal cell: the grapheme drawn there and its colours.
47	// A grapheme wider than one cell occupies several: the first holds the glyph,
48	// the following ones have an empty Glyph and the same colours.
49	type Cell struct {
50		Glyph  string
51		FG, BG string
52	}
53	
54	// Pos is a cell's position in a frame, zero-based.
55	type Pos struct{ Row, Col int }
56	
57	// Cells decodes a frame into one row of cells per line. A frame without a
58	// newline is one row; an empty frame is one empty row. The rows are as long as
59	// what was written: a row shorter than the screen is not padded.
60	func Cells(frame string) [][]Cell {
61		rows := [][]Cell{nil}
62		var st sgrState
63		p := ansi.NewParser()
64		var state byte
65		for rest := frame; len(rest) > 0; {
66			var seq string
67			var width, n int
68			seq, width, n, state = ansi.DecodeSequence(rest, state, p)
69			rest = rest[n:]
70			switch {
71			case seq == "\n":
72				rows = append(rows, nil)
73			case width > 0:
74				fg, bg := st.colours()
75				last := len(rows) - 1
76				rows[last] = append(rows[last], Cell{Glyph: seq, FG: fg, BG: bg})
77				for i := 1; i < width; i++ {
78					rows[last] = append(rows[last], Cell{FG: fg, BG: bg})
79				}
80			case width == 0 && isZeroWidthText(seq):
81				// A combining mark or joiner the decoder did not cluster with the
82				// ASCII letter before it: it belongs to that cell.
83				attach(rows[len(rows)-1], seq)
84			case isSGR(seq, p):
85				st.apply(p.Params())
86			}
87		}
88		return rows
89	}
90	
91	// isZeroWidthText reports whether seq is zero-width printable text (a combining
92	// mark, a joiner, a variation selector), as opposed to a control or an escape
93	// sequence.
94	func isZeroWidthText(seq string) bool {
95		r, _ := utf8.DecodeRuneInString(seq)
96		return r >= 0xA0 && r != utf8.RuneError
97	}
98	
99	// attach appends seq to the glyph of the last glyph-bearing cell of row. In an
100	// empty row it is dropped: there is nothing to combine with.
101	func attach(row []Cell, seq string) {
102		for i := len(row) - 1; i >= 0; i-- {
103			if row[i].Glyph != "" {
104				row[i].Glyph += seq
105				return
106			}
107		}
108	}
109	
110	// BareCells returns the position of every cell whose background is the
111	// terminal's default, in reading order. A frame that sets its own background
112	// everywhere returns none (Rule 115). A cell the frame never wrote, because a
113	// row is shorter than the screen, is not in the frame and so not in the result:
114	// the caller checks the row lengths against the width it expects.
115	func BareCells(frame string) []Pos {
116		var out []Pos
117		for r, row := range Cells(frame) {
118			for c, cell := range row {
119				if cell.BG == DefaultColor {
120					out = append(out, Pos{Row: r, Col: c})
121				}
122			}
123		}
124		return out
125	}
126	
127	// isSGR reports whether seq, just decoded into p, is a plain CSI ... m.
128	func isSGR(seq string, p *ansi.Parser) bool {
129		if !strings.HasPrefix(seq, "\x1b[") {
130			return false
131		}
132		cmd := ansi.Cmd(p.Command())
133		return cmd.Final() == 'm' && cmd.Prefix() == 0 && cmd.Intermediate() == 0
134	}
135	
136	// sgrState is the colour part of the graphic rendition.
137	type sgrState struct {
138		fg, bg  string
139		reverse bool
140	}
141	
142	// colours returns the colours a cell drawn now has.
143	func (s *sgrState) colours() (fg, bg string) {
144		if !s.reverse {
145			return s.fg, s.bg
146		}
147		fg, bg = s.bg, s.fg
148		if fg == DefaultColor {
149			fg = ReversedDefaultBG
150		}
151		if bg == DefaultColor {
152			bg = ReversedDefaultFG
153		}
154		return fg, bg
155	}
156	
157	// apply follows one SGR sequence. An unreadable colour ends the sequence, as a
158	// terminal would not know where the next attribute starts.
159	func (s *sgrState) apply(params ansi.Params) {
160		if len(params) == 0 {
161			*s = sgrState{}
162			return
163		}
164		for i := 0; i < len(params); {
165			v := params[i].Param(0)
166			if params[i].HasMore() && v != 38 && v != 48 && v != 58 {
167				// A sub-parameter chain such as 4:3 (curly underline): none of it is
168				// a colour attribute, and a 0 inside it must not reset anything.
169				for i < len(params) && params[i].HasMore() {
170					i++
171				}
172				i++
173				continue
174			}
175			switch {
176			case v == 0:
177				*s = sgrState{}
178			case v == 7:
179				s.reverse = true
180			case v == 27:
181				s.reverse = false
182			case v >= 30 && v <= 37:
183				s.fg = paletteName(v - 30)
184			case v == 39:
185				s.fg = DefaultColor
186			case v >= 40 && v <= 47:
187				s.bg = paletteName(v - 40)
188			case v == 49:
189				s.bg = DefaultColor
190			case v >= 90 && v <= 97:
191				s.fg = paletteName(v - 90 + 8)
192			case v >= 100 && v <= 107:
193				s.bg = paletteName(v - 100 + 8)
194			case v == 38 || v == 48 || v == 58:
195				var c color.Color
196				n := ansi.ReadStyleColor(params[i:], &c)
197				if n == 0 {
198					return
199				}
200				switch v {
201				case 38:
202					s.fg = colourName(c)
203				case 48:
204					s.bg = colourName(c)
205				}
206				// 58 is the underline colour (Lip Gloss writes 58;2;r;g;b and 58;5;n
207				// for an invalid field, Rule 140). It is read to consume its
208				// parameters, which are not attributes of their own, and not tracked:
209				// it changes no cell's foreground or background.
210				i += n
211				continue
212			case v == 59:
213				// Resets the underline colour, which is not tracked: nothing to do.
214			}
215			i++
216		}
217	}
218	
219	// paletteName names palette entry n (0 to 255).
220	func paletteName(n int) string {
221		if n < 16 {
222			return fmt.Sprintf("ansi:%d", n)
223		}
224		return fmt.Sprintf("idx:%d", n)
225	}
226	
227	// colourName names a decoded colour.
228	func colourName(c color.Color) string {
229		switch c := c.(type) {
230		case ansi.IndexedColor:
231			return paletteName(int(c))
232		case ansi.BasicColor:
233			return paletteName(int(c))
234		}
235		r, g, b, _ := c.RGBA()
236		return fmt.Sprintf("#%02x%02x%02x", r>>8, g>>8, b>>8)
237	}
238	
239	// FormatCells renders decoded cells as a stable, readable text, for a golden
240	// file: a legend of the distinct styles (a foreground and a background, named
241	// in order of first appearance), then per row a glyph line and a style line.
242	// Both lines sit between bars so a trailing space can be seen. The style line
243	// has one character per cell; the glyph line has one glyph per grapheme, so a
244	// wide glyph is one character there and two in the style line.
245	//
246	//	styles
247	//	  0: fg=- bg=#1e1e2e
248	//	  1: fg=#cdd6f4 bg=#1e1e2e
249	//	rows 2
250	//	00 |ab |
251	//	   |011|
252	func FormatCells(rows [][]Cell) string {
253		type style struct{ fg, bg string }
254		ids := map[style]rune{}
255		var order []style
256		idOf := func(c Cell) rune {
257			k := style{c.FG, c.BG}
258			id, ok := ids[k]
259			if !ok {
260				id = styleRune(len(order))
261				ids[k] = id
262				order = append(order, k)
263			}
264			return id
265		}
266	
267		var body strings.Builder
268		fmt.Fprintf(&body, "rows %d\n", len(rows))
269		for r, row := range rows {
270			var glyphs, styles strings.Builder
271			for _, c := range row {
272				glyphs.WriteString(c.Glyph)
273				styles.WriteRune(idOf(c))
274			}
275			fmt.Fprintf(&body, "%02d |%s|\n   |%s|\n", r, glyphs.String(), styles.String())
276		}
277	
278		var out strings.Builder
279		out.WriteString("styles\n")
280		dash := func(s string) string {
281			if s == DefaultColor {
282				return "-"
283			}
284			return s
285		}
286		for i, k := range order {
287			fmt.Fprintf(&out, "  %c: fg=%s bg=%s\n", styleRune(i), dash(k.fg), dash(k.bg))
288		}
289		out.WriteString(body.String())
290		return out.String()
291	}
292	
293	// styleRune is the one-cell-wide character naming the i-th style: digits and
294	// letters first, then the Latin-1 and Latin Extended-A letters, all single
295	// width.
296	func styleRune(i int) rune {
297		const alnum = "REDACTED"
298		if i < len(alnum) {
299			return rune(alnum[i])
300		}
301		return rune(0x100 + i - len(alnum))
302	}
