103	// checkFieldFits fails unless the view fits its box and shows the cursor cell,
104	// on the glyph the cursor really is on (a space after the last rune).
105	func checkFieldFits(t *testing.T, in textinput.Model) {
106		t.Helper()
107		view := in.View()
108		box := ansi.StringWidth(reseatPrompt) + in.Width() + 1 // prompt, text, cursor cell
109	
110		if got := ansi.StringWidth(view); got > box {
111			t.Errorf("width %d: the field is %d cells wide, its box holds %d: %q",
112				in.Width(), got, box, ansi.Strip(view))
113		}
114		cols, glyphs := reverseCells(view)
115		if len(cols) != 1 {
116			t.Fatalf("width %d: %d cursor cells in the view, want 1: %q", in.Width(), len(cols), ansi.Strip(view))
117		}
118		if cols[0] >= box {
119			t.Errorf("width %d: the cursor is in column %d, past the box of %d cells", in.Width(), cols[0], box)
120		}
121		want := " "
122		if runes := []rune(in.Value()); in.Position() < len(runes) {
123			want = string(runes[in.Position()])
124		}
125		if glyphs[0] != want {
126			t.Errorf("width %d: the cursor sits on %q, the rune at position %d is %q",
127				in.Width(), glyphs[0], in.Position(), want)
128		}
129	}
