151			name           string
152			pos            int
153			cursorOutOfBox bool // the cursor cell is beyond the box, not only the text
154		}{
155			{"cursor right of the middle", 70, true},
156			{"cursor in the middle", 40, false},
157			{"cursor at the start", 0, false},
158		}
