16	// DEVDESK-788 (step E3 of DEVDESK-785): bubbles scrolls a textinput through two
17	// internal offsets that only SetCursor, SetValue and Update refresh. After a
18	// SetWidth that shrinks the field, a cursor that still sits inside the old
19	// window leaves the old, too wide window in place: the view overflows its box
20	// and the cursor cell can land beyond it. ReseatInput rebuilds the window for
21	// the current width without touching what the user typed.
22	
23	// reseatPrompt is the prompt of the fields under test, two cells wide.
24	const reseatPrompt = "❯ "
25	
26	// reseatText is 80 runes, each one cell wide and each one different (Latin
27	// Extended-A and -B), so the glyph under the cursor tells where the window is.
28	func reseatText() string {
29		runes := make([]rune, 80)
30		for i := range runes {
31			runes[i] = rune(0x100 + i)
32		}
33		return string(runes)
34	}
35	
36	// reseatInput builds a focused field at width, holding reseatText with the
37	// cursor at pos.
38	func reseatInput(width, pos int) textinput.Model {
39		in := textinput.New()
40		in.Prompt = reseatPrompt
41		in.CharLimit = 0
42		in.Focus()
43		in.SetWidth(width)
44		in.SetValue(reseatText())
45		in.SetCursor(pos)
46		return in
47	}
48	
49	// reseatShrinkCases are the cursor positions of the 80-rune text the shrink is
50	// checked at. "right of middle" is the one a stale window hides from the frame.
51	var reseatShrinkCases = []struct {
52		name string
53		pos  int
54	}{
55		{"cursor at the end", 80},
56		{"cursor on the last rune", 79},
57		{"cursor right of the middle", 70},
58		{"cursor in the middle", 40},
59		{"cursor at the start", 0},
60	}
61	
62	// reseatWidths is the shrink the field goes through: it holds the whole text at
63	// 120, then has to scroll at 60 and again at 40.
64	var reseatWidths = []int{120, 60, 40}
65	
66	var sgrParams = regexp.MustCompile(`\x1b\[([0-9;]*)m`)
67	
68	// reverseCells returns the column and the glyph of every cell the view draws in
69	// reverse video: the virtual cursor, the only reversed thing a plain field has.
70	func reverseCells(view string) (cols []int, glyphs []string) {
71		col, reversed, rest := 0, false, view
72		for len(rest) > 0 {
73			loc := sgrParams.FindStringSubmatchIndex(rest)
74			text := rest
75			if loc != nil {
76				text = rest[:loc[0]]
77			}
78			if text != "" {
79				for _, g := range strings.Split(ansi.Strip(text), "") {
80					if reversed {
81						cols = append(cols, col)
82						glyphs = append(glyphs, g)
83					}
84					col += ansi.StringWidth(g)
85				}
86			}
87			if loc == nil {
88				break
89			}
90			for _, p := range strings.Split(rest[loc[2]:loc[3]], ";") {
91				switch p {
92				case "", "0", "27":
93					reversed = false
94				case "7":
95					reversed = true
96				}
97			}
98			rest = rest[loc[1]:]
99		}
100		return cols, glyphs
101	}
102	
103	// checkFieldFits fails unless the view fits its box and shows the cursor cell,
104	// on the glyph the cursor really is on (a space after the last rune).
105	func checkFieldFits(t *testing.T, in textinput.Model) {
106		t.Helper()
107		view := in.View()
108		box := ansi.StringWidth(reseatPrompt) + in.Width() + 1 // prompt, text, cursor cell
109	
110		if got := ansi.StringWidth(view); got > box {
111			t.Errorf("width %d: the field is %d cells wide, its box holds %d: %q",
112				in.Width(), got, box, ansi.Strip(view))
113		}
114		cols, glyphs := reverseCells(view)
115		if len(cols) != 1 {
116			t.Fatalf("width %d: %d cursor cells in the view, want 1: %q", in.Width(), len(cols), ansi.Strip(view))
117		}
118		if cols[0] >= box {
119			t.Errorf("width %d: the cursor is in column %d, past the box of %d cells", in.Width(), cols[0], box)
120		}
121		want := " "
122		if runes := []rune(in.Value()); in.Position() < len(runes) {
123			want = string(runes[in.Position()])
124		}
125		if glyphs[0] != want {
126			t.Errorf("width %d: the cursor sits on %q, the rune at position %d is %q",
127				in.Width(), glyphs[0], in.Position(), want)
128		}
129	}
130	
131	func TestReseatKeepsTheCursorVisibleAfterAShrink(t *testing.T) {
132		for _, tc := range reseatShrinkCases {
133			t.Run(tc.name, func(t *testing.T) {
134				in := reseatInput(reseatWidths[0], tc.pos)
135				for _, width := range reseatWidths[1:] {
136					in.SetWidth(width)
137					ReseatInput(&in)
138					checkFieldFits(t, in)
139				}
140			})
141		}
142	}
143	
144	// The defect, pinned without ReseatInput: SetWidth followed by SetCursor at the
145	// same position (what sizePaletteInput did before DEVDESK-788) keeps the old
146	// window whenever the cursor is still inside it. This passes today and goes
147	// red on the day bubbles refreshes its window on a width change (E0 moves
148	// bubbles to v2.2.2): the signal to retire ReseatInput, not a test to relax.
149	func TestShrinkWithoutReseatLeavesTheCursorOutside(t *testing.T) {
150		tests := []struct {
151			name           string
152			pos            int
153			cursorOutOfBox bool // the cursor cell is beyond the box, not only the text
154		}{
155			{"cursor right of the middle", 70, true},
156			{"cursor in the middle", 40, false},
157			{"cursor at the start", 0, false},
158		}
159		for _, tc := range tests {
160			t.Run(tc.name, func(t *testing.T) {
161				in := reseatInput(120, tc.pos)
162				in.SetWidth(40)
163				in.SetCursor(in.Position())
164	
165				view := in.View()
166				box := ansi.StringWidth(reseatPrompt) + in.Width() + 1
167				if got := ansi.StringWidth(view); got <= box {
168					t.Fatalf("the field is %d cells wide, within its box of %d: bubbles refreshes its window now", got, box)
169				}
170				if !tc.cursorOutOfBox {
171					return
172				}
173				cols, _ := reverseCells(view)
174				if len(cols) != 1 || cols[0] < box {
175					t.Errorf("cursor columns %v, want one at or past the box of %d cells", cols, box)
176				}
177			})
178		}
179	}
