181	func TestReseatKeepsValuePositionAndErr(t *testing.T) {
182		failed := errors.New("failed by the caller, not by a validator")
183		tests := []struct {
184			name  string
185			build func() textinput.Model
186		}{
187			{"cursor in the middle", func() textinput.Model { return reseatInput(120, 40) }},
188			{"cursor at the end", func() textinput.Model { return reseatInput(120, 80) }},
189			{"cursor at the start", func() textinput.Model { return reseatInput(120, 0) }},
190			{"error set by the caller", func() textinput.Model {
191				in := reseatInput(120, 40)
192				in.Err = failed
193				return in
194			}},
195			{"error from the validator", func() textinput.Model {
196				in := reseatInput(120, 40)
197				in.Validate = func(string) error { return failed }
198				in.SetValue(in.Value())
199				in.SetCursor(40)
200				return in
201			}},
202			{"empty field", func() textinput.Model {
203				in := reseatInput(120, 0)
204				in.SetValue("")
205				return in
206			}},
207		}
208		for _, tc := range tests {
209			t.Run(tc.name, func(t *testing.T) {
210				in := tc.build()
211				value, pos, err := in.Value(), in.Position(), in.Err
212				focused, limit := in.Focused(), in.CharLimit
213	
214				in.SetWidth(40)
215				ReseatInput(&in)
216	
217				if in.Value() != value {
218					t.Errorf("value %q, want %q", in.Value(), value)
219				}
220				if in.Position() != pos {
221					t.Errorf("position %d, want %d", in.Position(), pos)
222				}
223				if !errors.Is(in.Err, err) || (err == nil) != (in.Err == nil) {
224					t.Errorf("Err %v, want %v", in.Err, err)
225				}
226				if in.Focused() != focused || in.CharLimit != limit {
227					t.Errorf("focus %v and limit %d, want %v and %d", in.Focused(), in.CharLimit, focused, limit)
228				}
229			})
230		}
231	}
