233	func TestReseatKeepsTheSuggestions(t *testing.T) {
234		in := textinput.New()
235		in.Prompt = reseatPrompt
236		in.ShowSuggestions = true
237		in.Focus()
238		in.SetWidth(60)
239		in.SetSuggestions([]string{"deploy-staging", "deploy-production", "destroy", "logs"})
240		// Typed, not set: bubbles recomputes its matches when the user types.
241		for _, msg := range testutil.Type("de") {
242			in, _ = in.Update(msg)
243		}
244		in, _ = in.Update(testutil.Key("ctrl+n")) // the second match is now current
245	
246		available := slices.Clone(in.AvailableSuggestions())
247		matched := slices.Clone(in.MatchedSuggestions())
248		index, current := in.CurrentSuggestionIndex(), in.CurrentSuggestion()
249		if len(matched) < 2 || index == 0 {
250			t.Fatalf("setup: matched %v, current index %d, want several matches and the second one current", matched, index)
251		}
252	
253		in.SetWidth(10)
254		ReseatInput(&in)
255	
256		if got := in.AvailableSuggestions(); !slices.Equal(got, available) {
257			t.Errorf("available suggestions %v, want %v", got, available)
258		}
259		if got := in.MatchedSuggestions(); !slices.Equal(got, matched) {
260			t.Errorf("matched suggestions %v, want %v", got, matched)
261		}
262		if in.CurrentSuggestionIndex() != index || in.CurrentSuggestion() != current {
263			t.Errorf("current suggestion %d %q, want %d %q",
264				in.CurrentSuggestionIndex(), in.CurrentSuggestion(), index, current)
265		}
266	}
